, "old", "random", "qa", "live"], "type": "string", "examples": ["top", "new", "old"], "description": "Comment sort order. Valid values: confidence (default, 'best'), top, new, controversial, old, random, qa, live. If omitted, Reddit uses the subreddit's or user's default sort."}, "depth": {"type": "integer", "examples": [3, 5], "description": "Maximum nesting depth of the comment tree to return. Deeper replies are collapsed into 'more' placeholders instead of being expanded. Reddit's docs don't state a fixed bound."}, "limit": {"type": "integer", "examples": [50, 100], "description": "Maximum number of comments to return. Reddit's docs don't state a fixed bound for this endpoint; omit to use Reddit's own default."}, "article": {"type": "string", "examples": ["q5u7q5", "13a9zao"], "minLength": 1, "description": "Base-36 ID of the Reddit post (e.g., 'q5u7q5'), typically found in the post's URL and not including the 't3_' prefix."}}}, "hasFullSchema": true}, "AIRTABLE_GET_RECORD": {"toolkit": "AIRTABLE", "tool_slug": "AIRTABLE_GET_RECORD", "description": "Retrieves a specific record from an Airtable table by its record ID. Requires a known, valid record ID obtained from listing records or another API call - this tool cannot search or list records. Use the list records tool to find record IDs. Empty field values are not returned in the response.", "input_schema": {"type": "object", "required": ["baseId", "tableIdOrName", "recordId"], "properties": {"baseId": {"type": "string", "examples": ["appXXXXXXXXXXXXXX"], "description": "ID of the Airtable base."}, "recordId": {"type": "string", "examples": ["rec4YsVV8cU6V4EiT", "recGoHq5YJGaUJX24"], "description": "ID of the record to retrieve. Must be a real record ID obtained from listing records or another API call. Format: starts with 'rec' followed by exactly 14 alphanumeric characters (e.g., 'rec4YsVV8cU6V4EiT'). This tool retrieves a single specific record - to list or search multiple records, use the list records tool in