: {"enum": ["basic", "stealth", "auto"], "type": "string", "examples": ["basic", "stealth", "auto"], "description": "Proxy type to use for requests."}, "maxAge": {"type": "integer", "examples": [0, 3600000, 172800000], "description": "Cache validity period in milliseconds. Default is 2 days."}, "mobile": {"type": "boolean", "default": false, "description": "If true, emulate a mobile device when scraping. Defaults to false."}, "actions": {"type": "array", "items": {"type": "object", "required": ["type"], "properties": {"key": {"type": "string", "examples": ["Enter", "Escape", "Tab"], "description": "Key to press (e.g., 'Enter', 'Escape')."}, "text": {"type": "string", "examples": ["Hello world", "user@example.com"], "description": "Text to be typed into an element."}, "type": {"type": "string", "examples": ["click", "write", "wait", "press", "scroll"], "description": "The type of browser action to perform on the page before scraping. Supported actions: 'wait', 'click', 'screenshot', 'write', 'press', 'scroll'."}, "selector": {"type": "string", "examples": ["#submit-button", ".product-title"], "description": "CSS selector for the HTML element targeted by the action."}, "milliseconds": {"type": "integer", "examples": [500, 1000, 2000], "description": "Duration in milliseconds for the action."}}, "description": "Action to perform on the page"}, "description": "Browser actions to perform on each page before scraping."}, "formats": {"type": "array", "items": {"enum": ["markdown", "html", "rawHtml", "links", "screenshot", "json", "screenshot@fullPage"], "type": "string"}, "default": ["markdown"], "examples": [["markdown"], ["html", "screenshot"], ["json"]], "description": "Desired output formats for the scraped content. Defaults to ['markdown']."}, "headers": {"type": "object", "examples": [{"User-Agent": "CustomBot/1.0"}], "description": "Custom HTTP headers to send with each request.", "additionalProperties": {"type": "string"}}, "timeout": {"type": "integer", "examples"